/// never turn a client death into a red test. Any other error still
/// propagates loudly (script misuse surfaces as 500 responses, never as
/// handler exceptions).
Future<void> _serve(HttpRequest request) async {
  try {
    await _handle(request);
  } on HttpException {
    _abortedRequests++;
  } on SocketException {
    _abortedRequests++;
